changeSet.sql:
UPDATE theme SET tokens = tokens || $J${
  "bg-surface": "#161e27",
  "bg-surface-muted": "#0e151d",
  "cal-weekend": "#090f16",
  "cal-othermonth": "#080d13",
  "surface-othermonth": "linear-gradient(180deg, #0e151d, #090f16)"
}$J$::jsonb WHERE key = 'wave-03';

